import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem120 preserva campos operacionais',()=>{for(const [id,titulo,expected,link] of [["OTYBW2oIlOWx1MeHpF1u","Patinete Elétrico 500w 25km/h Dobrável App Bluetooth Rapido","Patinete elétrico dobrável — 500 W e 25 km/h anunciados","https://www.mercadolivre.com.br/up/MLBU3976859911?wid=MLB5243705479"],["OwXKuXw3ZMFmcvx7jF4v","Compressor Calibrador De Pneus Calibrador B&G Portátil Mini Digital Carro Bike Sem Fio Cor Preto","Calibrador portátil B&G sem fio — até 150 PSI anunciados","https://www.mercadolivre.com.br/p/MLB21163160?pdp_filters=item_id%3AMLB4705243893"]]){const p={id,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
